def topic_content(name: str, category: str) -> dict:
    if category == "hr":
        return {
            "definition": f"{name} is a common conversation area in interviews.",
            "why_it_matters": "Interviewers use the discussion to understand your experience, judgment, and communication.",
            "simple_explanation": "Answer honestly and use a specific example when one fits. Adapt the detail to the role and your own experience.",
            "example": "Use a brief situation, your action, and the outcome; explain what you learned.",
            "key_interview_points": ["Stay specific", "Use your own experience", "Connect relevant details to the role"],
            "quick_revision": ["Listen to the full question", "Organize the response", "Avoid memorized or universal claims"],
            "practice_prompts": [f"Practice answering: {name}.", "What example from your experience supports your response?"],
            "why_interviewers_ask": f"To understand your perspective and experience related to {name.casefold()}.",
            "what_to_include": ["A direct opening", "A relevant example", "A short reflection or outcome"],
            "suggested_structure": ["Context", "Your actions", "Result or learning", "Connection to the role"],
            "common_mistakes": ["Giving an overly general answer", "Claiming a universal perfect response", "Taking credit for a team's work without clarifying your contribution"],
        }
    if category == "professional-english":
        return {
            "definition": f"{name} focuses on clear, respectful communication in study and workplace settings.",
            "why_it_matters": "Clear language helps other people understand your point and next steps.",
            "simple_explanation": "Prefer familiar words, complete sentences, and a clear order. Review the audience and purpose before speaking or writing.",
            "example": "Instead of 'Send this fast', write 'Could you share the updated file by Thursday?'",
            "key_interview_points": ["Clarity", "Grammar", "Audience-appropriate tone"],
            "quick_revision": ["State the purpose", "Use concise sentences", "Check names, dates, and actions"],
            "practice_prompts": [f"Practice a short workplace example for {name.casefold()}.", "Rewrite one long sentence as two clear sentences."],
        }
    if category == "aptitude":
        return {
            "definition": f"{name} uses structured reasoning to solve a defined question.",
            "why_it_matters": "A repeatable method helps you check assumptions and reduce avoidable calculation errors.",
            "simple_explanation": "Identify the known values, choose a rule, solve one step at a time, and verify the result against the question.",
            "example": "Write the relevant equation before substituting numbers; estimate the answer to catch a misplaced decimal.",
            "key_interview_points": ["Read the wording carefully", "Show intermediate steps", "Check units and reasonableness"],
            "quick_revision": ["Known information", "Chosen rule", "Calculation", "Reasonableness check"],
            "practice_prompts": [f"Solve one short {name.casefold()} problem and explain each step.", "Estimate before calculating exactly."],
        }
    content = {
        "definition": f"{name} is a practical foundation topic in technical preparation.",
        "why_it_matters": "Understanding the core idea helps you explain design choices and reason through everyday development tasks.",
        "simple_explanation": f"Start with the purpose of {name.casefold()}, identify its inputs and outputs, and compare the trade-offs of common approaches.",
        "example": f"When using {name.casefold()} in a small project, describe the problem, the approach, and how you would check the result.",
        "key_interview_points": ["Explain the core idea in your own words", "Give a small example", "Mention a relevant trade-off"],
        "quick_revision": [f"Purpose: {name}", "Typical use", "One advantage and one limitation"],
        "practice_prompts": [f"Explain {name} to a classmate in two minutes.", f"Give one practical example involving {name.casefold()}.", "What is one limitation or trade-off?"],
    }
    if name in SPECIFIC_LESSONS:
        definition, explanation, example, interview_points, revision = SPECIFIC_LESSONS[name]
        content.update({"definition": definition, "simple_explanation": explanation, "example": example,
            "key_interview_points": interview_points, "quick_revision": revision})
    return content


def seed_learning_catalog(db: Session) -> None:
    """Insert InterviewHub-owned starter material once; never imports external or employer content."""
    category_by_slug = {item.slug: item for item in db.scalars(select(LearningCategory)).all()}
    for order, (name, slug, description, icon) in enumerate(CATEGORIES):
        category = category_by_slug.get(slug)
        if category is None:
            category = LearningCategory(name=name, slug=slug, description=description, icon=icon, display_order=order)
            db.add(category)
            db.flush()
            category_by_slug[slug] = category
    topic_sets = {"technical": TECH_TOPICS, "hr": HR_TOPICS, "aptitude": APTITUDE_TOPICS, "professional-english": ENGLISH_TOPICS}
    existing_topics = {(item.category_id, item.slug): item for item in db.scalars(select(LearningTopic)).all()}
    topic_by_name = {}
    for slug, names in topic_sets.items():
        category = category_by_slug[slug]
        for order, name in enumerate(names):
            topic = existing_topics.get((category.id, slugify(name)))
            if topic is None:
                topic = LearningTopic(category_id=category.id, name=name, slug=slugify(name),
                    description=f"A concise, practical introduction to {name.casefold()}.",
                    difficulty="Easy", content=topic_content(name, slug), estimated_minutes=8 if slug == "hr" else 10,
                    display_order=order)
                db.add(topic)
                db.flush()
                existing_topics[(category.id, topic.slug)] = topic
            topic_by_name[name] = topic
    existing_questions = set(db.execute(select(PracticeQuestion.topic_id, PracticeQuestion.question)
        .where(PracticeQuestion.source == "internal")).all())
    for topic_name, questions in QUESTIONS.items():
        topic = topic_by_name[topic_name]
        for question, options, correct, explanation in questions:
            if (topic.id, question) in existing_questions:
                continue
            db.add(PracticeQuestion(topic_id=topic.id, question=question, question_type="mcq", options=options,
                correct_answer=correct, explanation=explanation, difficulty=QUESTION_LEVELS.get(topic_name, "Easy"), source="internal", is_active=True))
            existing_questions.add((topic.id, question))
    db.commit()
